package io.earthplatform.minecraft.lod;

import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static io.earthplatform.minecraft.lod.RenderSubmissionProbe.Stage.*;

class RenderSubmissionProbeTest {
    static final class Clock implements RenderSubmissionProbe.Clock {
        long wall=100,cpu=10,utc=1000,readCost;int utcReads;boolean missing,throwCpu;
        public long nanos(){return wall;}
        public long cpuNanos(){wall+=readCost;if(throwCpu)throw new UnsupportedOperationException("CPU unavailable");return missing?-1:cpu;}
        public long utcMillis(){utcReads++;return utc;}
        public String cpuStatus(){return "TEST";}
    }
    static com.google.gson.JsonObject stage(RenderSubmissionProbe p,RenderSubmissionProbe.Stage s){return p.diagnostics().getAsJsonObject("stages").getAsJsonObject(s.name());}
    static void span(RenderSubmissionProbe p,Clock c,RenderSubmissionProbe.Stage s,long wall,long cpu){long token=p.start(s,27,104);c.wall+=wall;c.cpu+=cpu;p.finish(s,token);}

    @Test void innerOperationAndOuterCpuReadBracketsArePreservedExactly(){var c=new Clock();c.readCost=3;var p=new RenderSubmissionProbe(true,c);p.setContext(9,2,7,4,true);span(p,c,FAR_DH,20,7);var d=stage(p,FAR_DH);assertEquals(20,d.get("maxInnerElapsedNanos").getAsLong());assertEquals(26,d.get("maxOuterElapsedNanos").getAsLong());assertEquals(7,d.get("maxValidThreadCpuNanos").getAsLong());var s=d.getAsJsonArray("worstElapsedSamples").get(0).getAsJsonObject();assertEquals(100,s.get("wallBeforeCpuStart").getAsLong());assertEquals(103,s.get("wallStart").getAsLong());assertEquals(123,s.get("wallEnd").getAsLong());assertEquals(126,s.get("wallAfterCpuEnd").getAsLong());assertEquals(10,s.get("cpuStart").getAsLong());assertEquals(17,s.get("cpuEnd").getAsLong());assertEquals(9,s.get("frame").getAsLong());assertTrue(s.get("historical").getAsBoolean());assertEquals(27,s.get("declaredOwners").getAsInt());assertEquals(104,s.get("declaredVertices").getAsLong());}
    @Test void cpuGreaterThanOuterIsNotClampedOrReinterpretedAsValidWallTime(){var c=new Clock();c.readCost=2;var p=new RenderSubmissionProbe(true,c);span(p,c,FAR_NATIVE,10,100);var d=stage(p,FAR_NATIVE);assertEquals(86,d.get("maxCpuExcessOverOuterWallNanos").getAsLong());assertEquals(1,d.get("cpuExceedsOuterWallSamples").getAsLong());var s=d.getAsJsonObject("worstCpuExcessSample");assertEquals(100,s.get("cpuDeltaNanos").getAsLong());assertEquals(14,s.get("outerElapsedNanos").getAsLong());assertEquals(86,s.get("cpuExcessOverOuterNanos").getAsLong());}
    @Test void worstCpuDiscrepancySurvivesLargerWallOnlySamples(){var c=new Clock();var p=new RenderSubmissionProbe(true,c);span(p,c,FAR_DH,1,100);for(int i=0;i<20;i++)span(p,c,FAR_DH,1000+i,0);var d=stage(p,FAR_DH);assertEquals(99,d.get("maxCpuExcessOverOuterWallNanos").getAsLong());assertEquals(1,d.getAsJsonObject("worstCpuExcessSample").get("innerElapsedNanos").getAsLong());assertEquals(3,d.getAsJsonArray("worstElapsedSamples").size());assertEquals(4,p.diagnostics().get("retainedSampleSlots").getAsInt());}
    @Test void unsupportedAndFailingCpuReadsRemainExplicitWithoutBreakingDraw(){var c=new Clock();var p=new RenderSubmissionProbe(true,c);c.missing=true;span(p,c,NEAR_DH,12,0);c.missing=false;c.throwCpu=true;span(p,c,NEAR_DH,13,0);var d=stage(p,NEAR_DH);assertEquals(2,d.get("cpuUnavailableSamples").getAsLong());assertEquals(0,d.get("cpuAvailableSamples").getAsLong());assertEquals(2,p.diagnostics().get("cpuReadFailures").getAsLong());assertEquals(-1,d.getAsJsonArray("worstElapsedSamples").get(0).getAsJsonObject().get("cpuStart").getAsLong());}
    @Test void cpuBackwardsIsSeparateFromUnavailableAndNotAddedToTotals(){var c=new Clock();var p=new RenderSubmissionProbe(true,c);span(p,c,NEAR_NATIVE,20,-5);var d=stage(p,NEAR_NATIVE);assertEquals(1,d.get("cpuBackwardsSamples").getAsLong());assertEquals(0,d.get("cpuUnavailableSamples").getAsLong());assertEquals(0,d.get("totalValidThreadCpuNanos").getAsLong());var s=d.getAsJsonArray("worstElapsedSamples").get(0).getAsJsonObject();assertEquals(10,s.get("cpuStart").getAsLong());assertEquals(5,s.get("cpuEnd").getAsLong());}
    @Test void wrappedNanoTimeOriginStillProducesCorrectPositiveDurations(){var c=new Clock();c.wall=Long.MAX_VALUE-10;var p=new RenderSubmissionProbe(true,c);span(p,c,FAR_DH,50,20);assertEquals(50,stage(p,FAR_DH).get("maxInnerElapsedNanos").getAsLong());assertEquals(0,stage(p,FAR_DH).get("wallAnomalies").getAsLong());}
    @Test void invalidWallDirectionIsCountedNotSummedIntoDurations(){var c=new Clock();var p=new RenderSubmissionProbe(true,c);span(p,c,FAR_DH,-1,0);var d=stage(p,FAR_DH);assertEquals(1,d.get("wallAnomalies").getAsLong());assertEquals(0,d.get("totalInnerElapsedNanos").getAsLong());}
    @Test void repeatedNormalFramesDoNotGrowHistoryOrReadUtcClock(){var c=new Clock();var p=new RenderSubmissionProbe(true,c);for(int i=0;i<10000;i++)span(p,c,FAR_DH,10,1);assertEquals(3,c.utcReads);assertEquals(3,p.diagnostics().get("retainedSampleSlots").getAsInt());assertEquals(10000,stage(p,FAR_DH).get("calls").getAsLong());}
    @Test void allStagesRemainWithinSixtyEightRawSlots(){var c=new Clock();var p=new RenderSubmissionProbe(true,c);for(var s:RenderSubmissionProbe.Stage.values())for(int i=0;i<10;i++){
        if(s.ordinal()<NATIVE_OWNER_CALL.ordinal()){span(p,c,s,i+1,100);continue;}
        long parent=p.start(FAR_NATIVE),owner=p.startNativePhase(NATIVE_OWNER_CALL,"mesh/layer/first");
        long body=s==NATIVE_OWNER_CALL?0:p.startNativePhase(NATIVE_VALIDATED_BODY,"mesh/layer/first");
        long leaf=s.ordinal()>NATIVE_VALIDATED_BODY.ordinal()?p.startNativePhase(s,"mesh/layer/first"):0;
        c.wall+=i+1;c.cpu+=100;
        if(leaf!=0)p.finish(s,leaf);if(body!=0)p.finish(NATIVE_VALIDATED_BODY,body);
        p.finish(NATIVE_OWNER_CALL,owner);p.finish(FAR_NATIVE,parent);
    }assertEquals(68,p.diagnostics().get("retainedSampleSlots").getAsInt());assertEquals(68,p.diagnostics().get("maxRetainedSamplesTotal").getAsInt());}
    @Test void retainedSamplesUseImmutableOriginalContextAndCachedCounts(){var c=new Clock();var p=new RenderSubmissionProbe(true,c);p.setContext(5,6,7,8,true);span(p,c,FAR_DH,10,1);p.setContext(10,11,12,13,false);var sample=stage(p,FAR_DH).getAsJsonArray("worstElapsedSamples").get(0).getAsJsonObject();assertEquals(5,sample.get("frame").getAsLong());assertEquals(6,sample.get("epoch").getAsLong());assertEquals(7,sample.get("publication").getAsLong());assertEquals(8,sample.get("resourceGeneration").getAsLong());assertTrue(sample.get("historical").getAsBoolean());}
    @Test void duplicateNestedStageAndWrongTokenFailWithoutLosingOriginalSpan(){var c=new Clock();var p=new RenderSubmissionProbe(true,c);long t=p.start(FAR_DH);assertThrows(IllegalStateException.class,()->p.start(FAR_DH));assertThrows(IllegalStateException.class,()->p.finish(FAR_DH,t+1));assertThrows(IllegalStateException.class,()->p.setContext(1,1,1,1,false));c.wall+=5;p.finish(FAR_DH,t);assertThrows(IllegalStateException.class,()->p.finish(FAR_DH,t));assertFalse(stage(p,FAR_DH).get("spanOpen").getAsBoolean());}
    @Test void separateStagesCanNestAndAreExplicitlyInclusive(){var c=new Clock();var p=new RenderSubmissionProbe(true,c);long a=p.start(FAR_DH);c.wall+=5;long b=p.start(FAR_NATIVE);c.wall+=10;p.finish(FAR_NATIVE,b);c.wall+=5;p.finish(FAR_DH,a);assertEquals(20,stage(p,FAR_DH).get("maxInnerElapsedNanos").getAsLong());assertEquals(10,stage(p,FAR_NATIVE).get("maxInnerElapsedNanos").getAsLong());}
    @Test void accountingSaturatesRatherThanOverflowing(){var c=new Clock();c.wall=0;var p=new RenderSubmissionProbe(true,c);for(int i=0;i<3;i++)span(p,c,FAR_DH,Long.MAX_VALUE/2,0);assertTrue(p.diagnostics().get("countersSaturated").getAsBoolean());assertEquals(Long.MAX_VALUE,stage(p,FAR_DH).get("totalInnerElapsedNanos").getAsLong());}
    @Test void failuresStillMeasureThroughCallerFinallyAndPreserveOriginalException(){var c=new Clock();var p=new RenderSubmissionProbe(true,c);var error=new IllegalStateException("draw");assertSame(error,assertThrows(IllegalStateException.class,()->{long token=p.start(FAR_DH);try{c.wall+=99;throw error;}finally{p.finish(FAR_DH,token);}}));assertEquals(99,stage(p,FAR_DH).get("maxInnerElapsedNanos").getAsLong());}
    @Test void enabledCallsEnforceOwnerAndDisabledPathTouchesNoClock() throws Exception {var c=new Clock();var p=new RenderSubmissionProbe(true,c);var failure=new AtomicReference<Throwable>();var thread=new Thread(()->{try{p.start(FAR_DH);}catch(Throwable e){failure.set(e);}});thread.start();thread.join();assertInstanceOf(IllegalStateException.class,failure.get());var disabled=new RenderSubmissionProbe(false,null);assertEquals(0,disabled.start(null,-9,-9));disabled.finish(null,99);disabled.setContext(0,0,0,0,false);assertFalse(disabled.diagnostics().get("enabled").getAsBoolean());}
    @Test void invalidCountsRejectBeforeOpeningSpan(){var c=new Clock();var p=new RenderSubmissionProbe(true,c);assertThrows(IllegalArgumentException.class,()->p.start(FAR_DH,-2,0));assertFalse(stage(p,FAR_DH).get("spanOpen").getAsBoolean());long t=p.start(FAR_DH);p.finish(FAR_DH,t);assertEquals(-1,stage(p,FAR_DH).getAsJsonArray("worstElapsedSamples").get(0).getAsJsonObject().get("declaredOwners").getAsInt());}
    @Test void slowThresholdAndStageCardinalityAreIndependentOfDepthPasses(){var c=new Clock();var p=new RenderSubmissionProbe(true,c);span(p,c,FAR_DH,49_999_999,0);span(p,c,FAR_DH,50_000_000,0);span(p,c,NEAR_DH,60_000_000,0);assertEquals(1,stage(p,FAR_DH).get("slowCalls").getAsLong());assertEquals(1,stage(p,NEAR_DH).get("slowCalls").getAsLong());assertEquals(2,stage(p,FAR_DH).get("calls").getAsLong());}
}
